```javascript
// db.js
import Dexie from 'dexie';

class InstacartDB extends Dexie {
  constructor() {
    super('InstacartDB');
    this.version(1).stores({
      orders: '++id, orderId, status, updatedAt',
      products: '++id, orderId, productId',
      pendingActions: '++id, orderId, action, timestamp, synced',
      wsMessageQueue: '++id, type, payload, receivedAt'
    });
  }
}

const db = new InstacartDB();

// Optimistic update pattern
async function updateOrderStatus(orderId, newStatus) {
  const tempId = crypto.randomUUID();
  await db.pendingActions.add({ orderId, action: 'status_update', payload: { status: newStatus }, timestamp: Date.now(), synced: false });
  await db.orders.update(orderId, { status: newStatus, updatedAt: Date.now() });
  return tempId;
}
```

## WebSocket with Exponential Backoff + Jitter

```javascript
class OrderTracker {
  constructor() {
    this.baseDelay = 1000;
    this.maxDelay = 30000;
    this.reconnectAttempt = 0;
  }

  getReconnectDelay() {
    const exponentialDelay = Math.min(
      this.baseDelay * Math.pow(2, this.reconnectAttempt),
      this.maxDelay
    );
    const jitter = Math.random() * 0.3 * exponentialDelay;
    return exponentialDelay + jitter;
  }

  connect() {
    this.ws = new WebSocket('wss://api.instacart.com/orders/live');

    this.ws.onclose = () => {
      this.reconnectAttempt++;
      setTimeout(() => this.connect(), this.getReconnectDelay());
    };

    this.ws.onmessage = (event) => {
      const update = JSON.parse(event.data);
      this.handleOrderUpdate(update);
    };
  }

  async handleOrderUpdate(update) {
    await db.wsMessageQueue.add({ type: update.type, payload: update, receivedAt: Date.now() });
    await db.orders.update(update.orderId, { ...update, updatedAt: Date.now() });
  }
}
```

## Conflict Resolution Strategy

```javascript
// Server sends vector clock with each update
// Client maintains local version vector

class ConflictResolver {
  resolve(localOrder, remoteUpdate, localVector, remoteVector) {
    if (this.isConcurrent(localVector, remoteVector)) {
      return this.mergeOrderState(localOrder, remoteUpdate);
    }
    return this.isNewer(remoteVector, localVector) ? remoteUpdate : localOrder;
  }

  mergeOrderState(local, remote) {
    return {
      ...remote,
      items: this.mergeItems(local.items, remote.items),
      status: this.prioritizeStatus(local.status, remote.status),
      estimatedDelivery: remote.estimatedDelivery || local.estimatedDelivery
    };
  }

  prioritizeStatus(local, remote) {
    const order = ['pending', 'confirmed', 'picking', '包装', 'delivering', 'delivered'];
    return order.indexOf(remote) > order.indexOf(local) ? remote : local;
  }
}
```

## UI State Management

```javascript
// Use React Query + custom hook for offline-aware state
function useOrderTracking(orderId) {
  const queryClient = useQueryClient();

  return useMutation({
    mutationFn: (update) => updateOrderStatus(orderId, update),
    onMutate: async (newStatus) => {
      await queryClient.cancelQueries(['order', orderId]);
      const previous = queryClient.getQueryData(['order', orderId]);
      queryClient.setQueryData(['order', orderId], (old) => ({
        ...old, status: newStatus, _optimistic: true
      }));
      return { previous };
    },
    onError: (err, vars, context) => {
      queryClient.setQueryData(['order', orderId], context.previous);
    },
    onSettled: () => {
      queryClient.invalidateQueries(['order', orderId]);
    }
  });
}
```

